1	import React, { useEffect, useState } from 'react';
2	import { Box, chakra, VStack, Flex } from '@chakra-ui/react';
3	import { FormattedMessage } from 'react-intl';
4	import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';
5	import { ZimmTable } from 'app/components/ui-kits/atoms/zimmTable';
6	import { isBlankRichText } from 'app/utils/richText';
7	import type { ContentfulRichText, SizeGuideEntry, SizeGuideTable } from 'app/types/contentful';
8	
9	export type SizeGuideContentProps = {
10	  sizeFit?: string;
11	  sizeGuide: SizeGuideEntry | null;
12	};
13	
14	type Unit = 'cm' | 'inch';
15	
16	// Mirrors foundation/gridSystem breakpoints.md (768px = 48em). Media queries cannot consume
17	// CSS vars, so this is the one deliberate exception to the var(--zimm-*) convention (css.md > Tokens).
18	const TABLET_MIN_WIDTH = '48em';
19	
20	const CM_TO_INCH = 0.393701;
21	
22	export const convertCm = (n: number) => Math.round(n * CM_TO_INCH * 10) / 10;
23	
24	/** Converts a single table's rows to display-ready values for the active unit. */
25	export const toDisplayRows = (table: SizeGuideTable, unit: Unit) =>
26	  table.rows.map((row) => ({
27	    label: row.label,
28	    spans: row.spans,
29	    isHeader: row.isHeader,
30	    cells: row.values.map((v) => {
31	      if (!row.convertible || unit !== 'inch') return v;
32	      const str = String(v);
33	      const rangeMatch = str.match(/^(\d+(?:\.\d+)?)\s*[–-]\s*(\d+(?:\.\d+)?)$/);
34	      if (rangeMatch) return `${convertCm(parseFloat(rangeMatch[1]))}–${convertCm(parseFloat(rangeMatch[2]))}`;
35	      if (typeof v === 'number') return convertCm(v);
36	      const trimmed = str.trim();
37	      if (!/^\d+(?:\.\d+)?$/.test(trimmed)) return v;
38	      return convertCm(Number(trimmed));
39	    }),
40	  }));
41	
42	/** Minimal inline renderer for Contentful Rich Text documents (paragraphs + bold/italic marks). */
43	const renderMeasurementInstructions = (doc: ContentfulRichText): React.ReactNode =>
44	  doc.content.map((block, i) => {
45	    if (block.nodeType !== 'paragraph' || !block.content) return null;
46	    return (
47	      <chakra.p key={i} textStyle="caption" color="var(--zimm-color-text-default)" margin={0}>
48	        {block.content.map((inline, j) => {
49	          if (inline.nodeType !== 'text') return null;
50	          let node: React.ReactNode = inline.value ?? '';
51	          if (inline.marks?.some((m) => m.type === 'bold')) node = <strong key={j}>{node}</strong>;
52	          if (inline.marks?.some((m) => m.type === 'italic')) node = <em key={j}>{node}</em>;
53	          return <React.Fragment key={j}>{node}</React.Fragment>;
54	        })}
55	      </chakra.p>
56	    );
57	  });
58	
59	type NavItemProps = { label: string; active: boolean; onClick: () => void };
60	type UnitToggleProps = { unit: Unit; onChange: (u: Unit) => void };
61	type TableSectionProps = {
62	  heading?: React.ReactNode;
63	  description?: string;
64	  toggle?: React.ReactNode;
65	  children: React.ReactNode;
66	};
67	type ScrollableTableProps = { table: SizeGuideTable; unit: Unit };
68	type ConvertibleTableSectionProps = {
69	  table: SizeGuideTable;
70	  heading?: React.ReactNode;
71	  description?: string;
72	  showToggle: boolean;
73	  initialUnit: Unit;
74	};
75	
76	const NavItem = ({ label, active, onClick }: NavItemProps) => (
77	  <chakra.button
78	    height="var(--zimm-scale-xl)"
79	    display="flex"
80	    flexDirection="column"
81	    alignItems="flex-start"
82	    justifyContent="center"
83	    flexShrink={0}
84	    sx={{ background: 'none', padding: 0, borderWidth: 0, cursor: 'pointer' }}
85	    aria-pressed={active}
86	    onClick={onClick}
87	  >
88	    <chakra.span
89	      display="flex"
90	      alignItems="center"
91	      paddingY="var(--zimm-scale-2xs)"
92	      sx={{
93	        borderBottomWidth: active ? 'var(--zimm-border-width-default)' : 0,
94	        borderBottomStyle: 'solid',
95	        borderBottomColor: active ? 'var(--zimm-color-border-focus)' : 'transparent',
96	      }}
97	    >
98	      <chakra.span
99	        textStyle="navigation"
100	        color="var(--zimm-color-text-default)"
101	        sx={{ whiteSpace: 'nowrap' }}
102	      >
103	        {label}
104	      </chakra.span>
105	    </chakra.span>
106	  </chakra.button>
107	);
108	
109	const UnitToggle = ({ unit, onChange }: UnitToggleProps) => (
110	  <Flex gap="var(--zimm-scale-2xs)" role="group" aria-label="Unit" align="center">
111	    <NavItem label="CM" active={unit === 'cm'} onClick={() => onChange('cm')} />
112	    <chakra.span
113	      height="var(--zimm-scale-xl)"
114	      display="flex"
115	      flexDirection="column"
116	      alignItems="flex-start"
117	      justifyContent="center"
118	      flexShrink={0}
119	    >
120	      <chakra.span display="flex" alignItems="center" paddingY="var(--zimm-scale-2xs)">
121	        <chakra.span textStyle="navigation" color="var(--zimm-color-text-muted)" aria-hidden="true">
122	          |
123	        </chakra.span>
124	      </chakra.span>
125	    </chakra.span>
126	    <NavItem label="INCH" active={unit === 'inch'} onClick={() => onChange('inch')} />
127	  </Flex>
128	);
129	
130	/**
131	 * One table section: a Flex header row (heading left, optional toggle right), an optional
132	 * description paragraph, then the table. Spacing matches the Size Guide drawer design (SFCC-102).
133	 */
134	const TableSection = ({ heading, description, toggle, children }: TableSectionProps) => (
135	  <VStack align="stretch" spacing="var(--zimm-scale-2xl)" width="100%">
136	    {(heading || toggle) && (
137	      <Flex justify="space-between" align="center" width="100%">
138	        {heading && (
139	          <chakra.h2 textStyle="productNames" color="var(--zimm-color-text-default)" margin={0}>
140	            {heading}
141	          </chakra.h2>
142	        )}
143	        {toggle}
144	      </Flex>
145	    )}
146	    {description && (
147	      <chakra.p textStyle="caption" color="var(--zimm-color-text-default)" margin={0}>
148	        {description}
149	      </chakra.p>
150	    )}
151	    {children}
152	  </VStack>
153	);
154	
155	/**
156	 * Wraps a ZimmTable with a right-edge fade on mobile to hint at horizontal scroll.
157	 * Outer Box is position:relative with an ::after pseudo-element for the fade gradient;
158	 * inner Box handles overflow-x:auto so the pseudo-element is not clipped.
159	 */
160	const ScrollableTable = ({ table, unit }: ScrollableTableProps) => (
161	  <Box
162	    position="relative"
163	    sx={{
164	      _after: {
165	        content: '""',
166	        position: 'absolute',
167	        top: 0,
168	        right: 0,
169	        bottom: 0,
170	        width: 'calc(var(--zimm-scale-4xl) + var(--zimm-scale-xs))',
171	        pointerEvents: 'none',
172	        zIndex: 1,
173	        background: `linear-gradient(to right, transparent, var(--zimm-color-grey-white))`,
174	        display: 'block',
175	      },
176	      [`@media (min-width: ${TABLET_MIN_WIDTH})`]: {
177	        _after: { display: 'none' },
178	      },
179	    }}
180	  >
181	    <Box overflowX="auto">
182	      <ZimmTable
183	        columns={table.labelless ? [] : ['SIZE', ...table.columns]}
184	        columnSpan={table.columnSpan}
185	        subColumns={table.subColumns}
186	        rows={toDisplayRows(table, unit)}
187	        labelless={table.labelless}
188	        bordered={table.labelless}
189	      />
190	    </Box>
191	  </Box>
192	);
193	
194	/**
195	 * Self-contained table section that manages its own cm/inch unit state independently.
196	 * Each instance's toggle only affects its own table, not sibling tables.
197	 */
198	const ConvertibleTableSection = ({
199	  table,
200	  heading,
201	  description,
202	  showToggle,
203	  initialUnit,
204	}: ConvertibleTableSectionProps) => {
205	  const [unit, setUnit] = useState<Unit>(initialUnit);
206	
207	  useEffect(() => {
208	    setUnit(initialUnit);
209	  }, [initialUnit, table]);
210	
211	  const hasConvertibleRows = table.rows.some((r) => r.convertible);
212	
213	  return (
214	    <TableSection
215	      heading={heading}
216	      description={description}
217	      toggle={showToggle && hasConvertibleRows ? <UnitToggle unit={unit} onChange={setUnit} /> : undefined}
218	    >
219	      <ScrollableTable table={table} unit={unit} />
220	    </TableSection>
221	  );
222	};
223	
224	// Contentful's Object type has no structural validation — a published table field can be {}
225	// (or any other truthy object). Guard before passing to toDisplayRows/ZimmTable, which call
226	// table.rows.map/some unconditionally and throw on undefined.
227	const isValidTable = (t: SizeGuideTable): boolean =>
228	  Array.isArray(t.columns) &&
229	  Array.isArray(t.rows) &&
230	  t.rows.every((r) => r !== null && typeof r === 'object' && Array.isArray(r.values));
231	
232	export const SizeGuideContent = ({ sizeFit, sizeGuide }: SizeGuideContentProps) => {
233	  const rawDefault = sizeGuide?.fields.defaultUnit;
234	  const initialUnit: Unit = rawDefault === 'cm' || rawDefault === 'inch' ? rawDefault : 'cm';
235	
236	  const { fields } = sizeGuide ?? {};
237	  const sizeConversionsTable =
238	    fields?.sizeConversionsTable && isValidTable(fields.sizeConversionsTable)
239	      ? fields.sizeConversionsTable
240	      : undefined;
241	  const bodyMeasurementsTable =
242	    fields?.bodyMeasurementsTable && isValidTable(fields.bodyMeasurementsTable)
243	      ? fields.bodyMeasurementsTable
244	      : undefined;
245	  const garmentMeasurementsTable =
246	    fields?.garmentMeasurementsTable && isValidTable(fields.garmentMeasurementsTable)
247	      ? fields.garmentMeasurementsTable
248	      : undefined;
249	  const hasTables = !!sizeConversionsTable || !!bodyMeasurementsTable || !!garmentMeasurementsTable;
250	
251	  // Normalise the fallback image URL to https and pre-build responsive variants using the
252	  // Contentful Images API (?w + ?fm without ?h/fit=fill so the image is width-constrained
253	  // rather than cropped to a fixed box — aspect ratio of this editorial asset is unknown).
254	  // Sizes: drawer content fills 100vw on mobile, capped at ~600px on tablet+ (TABLET_MIN_WIDTH).
255	  // Quality matches contentfulImage.ts's established constants (AVIF_QUALITY=65, WEBP_QUALITY=95).
256	  const fallbackImgBase = fields?.image
257	    ? fields.image.fields.file.url.startsWith('//')
258	      ? `https:${fields.image.fields.file.url}`
259	      : fields.image.fields.file.url
260	    : null;
261	
262	  return (
263	    <VStack align="stretch" spacing="var(--zimm-scale-4xl)" width="100%">
264	      {/* Size & fit copy from SFCC c_sizeFit — rendered directly, no section heading */}
265	      {!isBlankRichText(sizeFit) && <ZimmProductDescription description={sizeFit} />}
266	
267	      {/* Contentful size guide tables */}
268	      {sizeGuide && (
269	        <>
270	          {fields?.measurementInstructions && (
271	            <VStack align="stretch" spacing="var(--zimm-scale-xs)" width="100%">
272	              {renderMeasurementInstructions(fields.measurementInstructions)}
273	            </VStack>
274	          )}
275	
276	          {sizeConversionsTable && (
277	            <ConvertibleTableSection
278	              table={sizeConversionsTable}
279	              heading={
280	                sizeConversionsTable.hideHeading
281	                  ? undefined
282	                  : sizeConversionsTable.heading ?? (
283	                      <FormattedMessage
284	                        defaultMessage="SIZE CONVERSIONS"
285	                        id="product_detail.size_guide.heading.size_conversions"
286	                      />
287	                    )
288	              }
289	              description={fields?.sizeConversionsDescription}
290	              showToggle={!!fields?.hasCmInchToggle}
291	              initialUnit={initialUnit}
292	            />
293	          )}
294	
295	          {bodyMeasurementsTable && (
296	            <ConvertibleTableSection
297	              table={bodyMeasurementsTable}
298	              heading={
299	                bodyMeasurementsTable.hideHeading
300	                  ? undefined
301	                  : bodyMeasurementsTable.heading ?? (
302	                      <FormattedMessage
303	                        defaultMessage="BODY MEASUREMENTS"
304	                        id="product_detail.size_guide.heading.body_measurements"
305	                      />
306	                    )
307	              }
308	              description={fields?.bodyMeasurementsDescription}
309	              showToggle={!!fields?.hasCmInchToggle}
310	              initialUnit={initialUnit}
311	            />
312	          )}
313	
314	          {garmentMeasurementsTable && (
315	            <ConvertibleTableSection
316	              table={garmentMeasurementsTable}
317	              heading={
318	                garmentMeasurementsTable.hideHeading
319	                  ? undefined
320	                  : garmentMeasurementsTable.heading ?? (
321	                      <FormattedMessage
322	                        defaultMessage="GARMENT MEASUREMENTS"
323	                        id="product_detail.size_guide.heading.garment_measurements"
324	                      />
325	                    )
326	              }
327	              description={fields?.garmentMeasurementsDescription}
328	              showToggle={!!fields?.hasCmInchToggle}
329	              initialUnit={initialUnit}
330	            />
331	          )}
332	
333	          {/* Fallback image — only when all three tables are absent */}
334	          {!hasTables && fallbackImgBase && (
335	            <chakra.picture display="block" width="100%">
336	              <source
337	                type="image/avif"
338	                srcSet={`${fallbackImgBase}?w=800&fm=avif&q=65 1x, ${fallbackImgBase}?w=1600&fm=avif&q=65 2x`}
339	                sizes={`(min-width: ${TABLET_MIN_WIDTH}) 600px, 100vw`}
340	              />
341	              <chakra.img
342	                src={`${fallbackImgBase}?w=800&fm=webp&q=95`}
343	                srcSet={`${fallbackImgBase}?w=800&fm=webp&q=95 1x, ${fallbackImgBase}?w=1600&fm=webp&q=95 2x`}
344	                sizes={`(min-width: ${TABLET_MIN_WIDTH}) 600px, 100vw`}
345	                alt={fields?.label ?? ''}
346	                width="100%"
347	                display="block"
348	                loading="lazy"
349	              />
350	            </chakra.picture>
351	          )}
352	        </>
353	      )}
354	    </VStack>
355	  );
356	};
